// AiXenix Cosmos Lab web client: converts the cosmos model's drawing sample into the map's DrawSample (shared by the
// main thread and the sample worker; no other imports, so the worker bundle stays small).

import type { DrawSample } from '../render/UniverseView';

/** The model's sample, in either published shape (density cells with weights, or exact stars with ids). */
export interface RawSample {
  count?: number;
  frame?: 'galaxy' | 'universe';
  ids?: Float64Array;
  positions: Float32Array;
  colors: Float32Array;
  brightness?: Float32Array;
  weights?: Float32Array;
  representedStars?: number;
  represents?: number;
}

export function toDrawSample(galaxyId: string, s: RawSample): DrawSample {
  const count = s.count ?? Math.floor(s.positions.length / 3);
  let brightness = s.brightness;
  if (!brightness) {
    brightness = new Float32Array(count);
    const w = s.weights;
    let max = 0;
    if (w) for (let i = 0; i < count; i++) max = Math.max(max, w[i]!);
    for (let i = 0; i < count; i++) brightness[i] = w && max > 0 ? w[i]! / max : 1;
  }
  return {
    galaxyId,
    count,
    // Ids only when the model says these are its stars; the frame defaults by shape (ids: galaxy-local, cells: universe).
    ids: s.ids ?? null,
    frame: s.frame ?? (s.ids ? 'galaxy' : 'universe'),
    positions: s.positions,
    colors: s.colors,
    brightness,
    represents: s.representedStars ?? s.represents ?? 0,
  };
}

