// AiXenix Cosmos Lab web client: the one guard every world replacement goes through (catalogue worlds, generated
// systems from the Universe map, deep links, imports). An edited or time-advanced world asks Save first / Discard /
// Cancel before anything is loaded; Cancel leaves the physics world exactly as it is.

import { tx } from '../content/catalog';
import type { Lang } from '../content/catalog';
import { askConfirm } from './notices';
import { isDirty, saveToBrowser, sessionStore } from './session';
import { settingsStore, t } from './settings';

export function defaultSaveName(lang: Lang): string {
  const s = sessionStore.get();
  const scene = tx(s.scene?.name, lang) || s.snapshot?.sceneId || 'World';
  const d = new Date();
  const p = (n: number) => String(n).padStart(2, '0');
  return `${scene} ${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`;
}

/** Resolves true when it is fine to replace the current world (nothing unsaved, saved first, or discarded). */
export async function confirmReplace(): Promise<boolean> {
  if (!isDirty(sessionStore.get())) return true;
  const choice = await askConfirm({
    title: t('sandbox.discardTitle'),
    body: t('sandbox.discardBody'),
    confirm: t('sandbox.discardGo'),
    cancel: t('common.cancel'),
    alternate: t('sandbox.discardSave'),
    danger: true,
  });
  if (choice === 'cancel') return false;
  if (choice === 'alternate') return saveToBrowser(defaultSaveName(settingsStore.get().lang));
  return true;
}
