// AiXenix Cosmos Lab web client: adapter between the cosmos model (core, src/cosmos), the observed catalogue (content,
// src/content/cosmos.ts) and the universe map. The modules are loaded through globs so the app builds before they land.
// The universe is built once on the main thread (exact O(depth) queries); big drawing samples run in a worker.

import type { DrawSample, MapGalaxy, MapStar, NearResult, UniverseProvider, Vec3 } from '../render/UniverseView';
import type { LocalizedText } from '../content/catalog';

// ---- core's contract (types only; the module itself is loaded lazily through a glob) --------------------------------------

import type {
  CosmosScene,
  GalaxySummary,
  ModelStar,
  ObservedStar,
  ResolveResult,
  StarsNearResult,
  Universe,
  SampleOptions,
  SystemOptions,
} from '../cosmos/types';

export type CoreGalaxySummary = GalaxySummary;
export type CoreModelStar = ModelStar;
export type CoreObservedStar = ObservedStar;

interface CoreApi {
  buildUniverse(galaxies: unknown[], stars?: unknown[]): Universe;
  listGalaxies(u: Universe): GalaxySummary[];
  observedStars(u: Universe): ObservedStar[];
  resolveAddress(u: Universe, addr: string): ResolveResult;
  starById(u: Universe, galaxyId: string, id: number): ModelStar | null;
  starsNear(u: Universe, galaxyId: string, centrePc: Vec3, radiusPc: number, limit: number, opts?: { maxCells?: number }): StarsNearResult;
  sampleGalaxy(u: Universe, galaxyId: string, count: number, opts?: SampleOptions): RawSample;
  generateSystem(u: Universe, starOrAddress: ModelStar | string, opts?: SystemOptions): CosmosScene;
  generateSystemForObservedStar(u: Universe, star: ObservedStar, opts?: SystemOptions): CosmosScene;
  galaxyAt(u: Universe, posPc: Vec3): string | null;
  densityAt(u: Universe, galaxyId: string, posPc: Vec3): number;
  SUN_POSITION_PC: Vec3;
  COSMOS_MODEL_VERSION: string;
}

import type { CosmosSource, GalaxyInfo, KnownStar } from '../content/cosmos';

export interface ContentApi {
  COSMOS_GALAXIES: GalaxyInfo[];
  KNOWN_STARS: KnownStar[];
  sourcesOf(ids: string[]): CosmosSource[];
  ERR_KIND_LABELS: Record<string, LocalizedText>;
  PROVENANCE_LABELS: Record<'observed' | 'reconstructed' | 'procedural', { label: LocalizedText; tip: LocalizedText }>;
}

export { toDrawSample, type RawSample } from './cosmosSample';
import { toDrawSample, type RawSample } from './cosmosSample';

const coreModules = import.meta.glob<CoreApi>('../cosmos/index.ts');
const contentModules = import.meta.glob<ContentApi>('../content/cosmos.ts');

// ---- regions (content: src/content/cosmos-regions.ts; core: src/cosmos/regions.ts), both optional --------------------

/** Content's region record (structural subset used here). */
export interface RegionInfo {
  id: string;
  name: LocalizedText;
  kind: string; // 'root' | 'galaxy_group' | 'subgroup' | 'galaxy_cluster' | 'sky_region'
  kindLabel?: LocalizedText;
  association: string; // 'gravitationally_bound' | 'group' | 'loose_or_uncertain' | 'navigation_only'
  associationNote?: LocalizedText;
  parent: string | null;
  members: string[];
  children?: string[];
  anchorGalaxy?: string | null;
  description?: LocalizedText;
  distanceRangeKpc?: [number, number];
  sources?: string[];
}

interface RegionsContentApi {
  COSMOS_REGIONS: RegionInfo[];
  REGION_ORDER?: string[];
  ASSOCIATION_LABELS?: Record<string, { label: LocalizedText; tip?: LocalizedText }>;
}

interface Sphere {
  centrePc: Vec3;
  radiusPc: number;
}

interface RegionsCoreApi {
  boundsOfRegions(u: Universe, regions: { id: string; members: string[]; parent: string | null }[], opts?: { mode?: 'model' | 'disk' }): Map<string, Sphere>;
  catalogueBounds(u: Universe, opts?: { mode?: 'model' | 'disk' }): Sphere | null;
  regionBounds(u: Universe, ids: string[], opts?: { mode?: 'model' | 'disk' }): Sphere | null;
  fitDistance(sphere: Sphere, fovYDeg: number, aspect: number, margin?: number): number;
}

const regionContentModules = import.meta.glob<RegionsContentApi>('../content/cosmos-regions.ts');
const regionCoreModules = import.meta.glob<RegionsCoreApi>('../cosmos/regions.ts');

/** A region with its bounds (disk extents of all members, descendants included) and depth (top level = 1). */
export interface CosmosRegionView {
  info: RegionInfo;
  centrePc: Vec3;
  radiusPc: number;
  depth: number;
  /** All galaxies of the region, its subregions included. */
  allMembers: string[];
}

/** Fallback bounds when core's helper is absent: centroid of the members and the farthest member edge. */
function simpleBounds(galaxies: GalaxySummary[]): Sphere | null {
  if (!galaxies.length) return null;
  const c: Vec3 = [0, 0, 0];
  for (const g of galaxies) for (let i = 0; i < 3; i++) c[i]! += g.centrePc[i]! / galaxies.length;
  let r = 0;
  for (const g of galaxies) r = Math.max(r, Math.hypot(g.centrePc[0] - c[0], g.centrePc[1] - c[1], g.centrePc[2] - c[2]) + g.radiusPc);
  return { centrePc: c, radiusPc: Math.max(r, 1) };
}

export interface Cosmos {
  core: CoreApi;
  content: ContentApi | null;
  /** Navigation regions (empty when the region module is not in this build); never includes the root. */
  regions: CosmosRegionView[];
  regionOrder: string[];
  associationLabels: Record<string, { label: LocalizedText; tip?: LocalizedText }>;
  /** Bounds of the whole catalogue (the "nearby universe" overview). */
  catalogue: Sphere;
  region(id: string): CosmosRegionView | undefined;
  /** Regions containing a galaxy, innermost first. */
  regionsOf(galaxyId: string): CosmosRegionView[];
  /** Camera distance that frames a sphere in the given view. */
  fit(sphere: Sphere, fovYDeg: number, aspect: number): number;
  universe: Universe;
  galaxies: CoreGalaxySummary[];
  mapGalaxies: MapGalaxy[];
  observed: MapStar[];
  sunPc: Vec3;
  version: string;
  provider: UniverseProvider;
  galaxyInfo(id: string): ContentApi['COSMOS_GALAXIES'][number] | undefined;
  summary(id: string): CoreGalaxySummary | undefined;
  resolve(address: string): { ok: true; star: MapStar } | { ok: false; message: string };
}

/** The map's view of a star; `id` is the model's stable key ('c1.<galaxy>.<id36>' or 'obs.<id>'). */
export function toMapStar(s: ModelStar | ObservedStar): MapStar {
  return {
    id: s.key,
    provenance: s.provenance,
    galaxyId: s.galaxyId,
    positionPc: s.positionPc,
    teffK: s.teffK,
    luminositySun: s.luminositySun,
    name: s.name,
    raw: s,
  };
}

/** Shape hints for the far-view glow, by kind (the drawing only; the stars come from the model). */
function glowHints(kind: string, id: string): Pick<MapGalaxy, 'arms' | 'pitchDeg' | 'diskScale' | 'bulgeScale' | 'axisRatio'> {
  if (id === 'milky_way') return { arms: 4, pitchDeg: 12, diskScale: 0.17, bulgeScale: 0.08 };
  switch (kind) {
    case 'barred_spiral':
      return { arms: 2, pitchDeg: 14, diskScale: 0.22, bulgeScale: 0.1 };
    case 'spiral':
      return { arms: 2, pitchDeg: 16, diskScale: 0.24, bulgeScale: 0.1 };
    case 'lenticular':
      return { arms: 0, diskScale: 0.25, bulgeScale: 0.18 };
    case 'irregular':
    case 'dwarf_irregular':
      return { arms: 0, diskScale: 0.35, bulgeScale: 0.2 };
    case 'elliptical':
      return { axisRatio: 0.75, bulgeScale: 0.32 };
    default:
      return { axisRatio: 0.85, bulgeScale: 0.4 };
  }
}

// ---- worker for big samples ---------------------------------------------------------------------------------------------

let worker: Worker | null = null;
let workerFailed = false;
let reqSerial = 0;
const pending = new Map<number, (s: DrawSample | null) => void>();

function getWorker(): Worker | null {
  if (worker || workerFailed) return worker;
  try {
    worker = new Worker(new URL('./cosmos.worker.ts', import.meta.url), { type: 'module' });
    worker.onmessage = (e: MessageEvent) => {
      const d = e.data as { req: number; ok: boolean } & Partial<DrawSample>;
      const cb = pending.get(d.req);
      if (!cb) return;
      pending.delete(d.req);
      cb(d.ok ? (d as DrawSample) : null);
    };
    worker.onerror = () => {
      workerFailed = true;
      for (const cb of pending.values()) cb(null);
      pending.clear();
      worker?.terminate();
      worker = null;
    };
  } catch {
    workerFailed = true;
    worker = null;
  }
  return worker;
}

// ---- loading ------------------------------------------------------------------------------------------------------------

let loading: Promise<Cosmos> | null = null;

export function cosmosAvailable(): boolean {
  return !!coreModules['../cosmos/index.ts'];
}

export function loadCosmos(): Promise<Cosmos> {
  if (loading) return loading;
  loading = (async () => {
    const loadCore = coreModules['../cosmos/index.ts'];
    if (!loadCore) throw new Error('model-missing');
    const core = await loadCore();
    const loadContent = contentModules['../content/cosmos.ts'];
    const content = loadContent ? await loadContent() : null;
    const universe = core.buildUniverse(content?.COSMOS_GALAXIES ?? [], content?.KNOWN_STARS ?? []);
    const galaxies = core.listGalaxies(universe);
    const sunPc = core.SUN_POSITION_PC;
    const mapGalaxies: MapGalaxy[] = galaxies.map((g) => ({
      id: g.id,
      centrePc: g.centrePc,
      normal: g.normal,
      majorAxis: g.majorAxis,
      radiusPc: g.radiusPc,
      thicknessPc: g.thicknessPc,
      kind: g.kind,
      modelStarCount: g.modelStarCount,
      ...glowHints(g.kind, g.id),
    }));
    const observed = core.observedStars(universe).map(toMapStar);
    const version = String(core.COSMOS_MODEL_VERSION);

    // Regions: content's records with core's bounds (or a simple fallback); the root is the overview, not a region.
    const loadRegContent = regionContentModules['../content/cosmos-regions.ts'];
    const loadRegCore = regionCoreModules['../cosmos/regions.ts'];
    const regContent = loadRegContent ? await loadRegContent().catch(() => null) : null;
    const regCore = loadRegCore ? await loadRegCore().catch(() => null) : null;
    const known = new Set(galaxies.map((g) => g.id));
    const infos = (regContent?.COSMOS_REGIONS ?? []).filter((r) => r.kind !== 'root');
    const rootIds = new Set((regContent?.COSMOS_REGIONS ?? []).filter((r) => r.kind === 'root').map((r) => r.id));
    const byId = new Map(infos.map((r) => [r.id, r] as const));
    const depthOf = (r: RegionInfo): number => {
      let d = 1;
      let p = r.parent;
      const seen = new Set<string>();
      while (p && byId.has(p) && !seen.has(p)) {
        seen.add(p);
        d++;
        p = byId.get(p)!.parent;
      }
      return d;
    };
    const allMembersOf = (r: RegionInfo): string[] => {
      const out = new Set(r.members.filter((m) => known.has(m)));
      for (const c of infos) if (c.parent === r.id) for (const m of allMembersOf(c)) out.add(m);
      return [...out];
    };
    let coreBounds: Map<string, Sphere> | null = null;
    try {
      coreBounds = regCore ? regCore.boundsOfRegions(universe, infos.map((r) => ({ id: r.id, members: r.members, parent: r.parent && rootIds.has(r.parent) ? null : r.parent })), { mode: 'disk' }) : null;
    } catch {
      coreBounds = null;
    }
    const regions: CosmosRegionView[] = [];
    for (const r of infos) {
      const all = allMembersOf(r);
      const b = coreBounds?.get(r.id) ?? simpleBounds(galaxies.filter((g) => all.includes(g.id)));
      if (!b || !all.length) continue;
      regions.push({ info: r, centrePc: b.centrePc, radiusPc: b.radiusPc, depth: depthOf(r), allMembers: all });
    }
    // Never NaN: an empty catalogue gets a nominal sphere around the Sun.
    let catalogue: Sphere | null = null;
    try {
      catalogue = regCore ? regCore.catalogueBounds(universe, { mode: 'disk' }) : null;
    } catch {
      catalogue = null;
    }
    catalogue = catalogue ?? simpleBounds(galaxies) ?? { centrePc: sunPc, radiusPc: 1e5 };
    if (!catalogue.centrePc.every((x) => Number.isFinite(x)) || !(catalogue.radiusPc > 0)) catalogue = { centrePc: sunPc, radiusPc: 1e5 };
    const regionMap = new Map(regions.map((r) => [r.info.id, r] as const));
    const fit = (sphere: Sphere, fovYDeg: number, aspect: number): number => {
      if (regCore) {
        try {
          const d = regCore.fitDistance(sphere, fovYDeg, aspect, 1.12);
          if (Number.isFinite(d) && d > 0) return d;
        } catch {
          // fall through to the local formula
        }
      }
      const half = (Math.min(fovYDeg, 2 * Math.atan(Math.tan((fovYDeg * Math.PI) / 360) * aspect) * (180 / Math.PI)) * Math.PI) / 360;
      return (sphere.radiusPc * 1.12) / Math.sin(half);
    };

    const provider: UniverseProvider = {
      galaxies: mapGalaxies,
      observed,
      sunPc,
      sample(galaxyId, count) {
        const w = count >= 20000 ? getWorker() : null;
        if (w) {
          const req = ++reqSerial;
          return new Promise((resolve) => {
            pending.set(req, resolve);
            w.postMessage({ type: 'sample', req, galaxyId, count });
          });
        }
        // Small samples (and a worker failure) run here, bounded.
        try {
          const n = workerFailed ? Math.min(count, 40000) : count;
          return Promise.resolve(toDrawSample(galaxyId, core.sampleGalaxy(universe, galaxyId, n)));
        } catch {
          return Promise.resolve(null);
        }
      },
      near(galaxyId, centrePc, radiusPc, maxStars): NearResult | null {
        try {
          const r = core.starsNear(universe, galaxyId, centrePc, radiusPc, maxStars, { maxCells: 20000 });
          return { stars: r.stars.map(toMapStar), modelCountInRadius: r.modelCountInRadius, truncated: r.truncated };
        } catch {
          return null;
        }
      },
      density(galaxyId, positionPc) {
        try {
          const d = core.densityAt(universe, galaxyId, positionPc);
          return Number.isFinite(d) ? d : 0;
        } catch {
          return 0;
        }
      },
      starById(galaxyId, id) {
        try {
          const s = core.starById(universe, galaxyId, id);
          return s ? toMapStar(s) : null;
        } catch {
          return null;
        }
      },
    };

    return {
      core,
      content,
      regions,
      regionOrder: regContent?.REGION_ORDER ?? regions.map((r) => r.info.id),
      associationLabels: regContent?.ASSOCIATION_LABELS ?? {},
      catalogue,
      region: (id) => regionMap.get(id),
      regionsOf: (galaxyId) => regions.filter((r) => r.allMembers.includes(galaxyId)).sort((a, b) => b.depth - a.depth),
      fit,
      universe,
      galaxies,
      mapGalaxies,
      observed,
      sunPc,
      version,
      provider,
      galaxyInfo: (id) => content?.COSMOS_GALAXIES.find((g) => g.id === id),
      summary: (id) => galaxies.find((g) => g.id === id),
      resolve(address) {
        const a = address.trim();
        if (a.startsWith('obs.')) {
          const s = observed.find((o) => o.id === a);
          return s ? { ok: true, star: s } : { ok: false, message: 'unknown observed star' };
        }
        try {
          const r = core.resolveAddress(universe, a);
          return r.ok ? { ok: true, star: toMapStar(r.star) } : { ok: false, message: r.message || r.error };
        } catch (e) {
          return { ok: false, message: e instanceof Error ? e.message : String(e) };
        }
      },
    } satisfies Cosmos;
  })();
  loading.catch(() => {
    loading = null;
  });
  return loading;
}

/** Builds the local system scene for a star (procedural: from its address; observed: from its catalogue values). */
export function systemFor(c: Cosmos, star: MapStar, opts: { hypotheticalPlanets?: boolean } = {}): CosmosScene {
  if (star.provenance === 'procedural') return c.core.generateSystem(c.universe, star.id, { maxBodies: 12 });
  return c.core.generateSystemForObservedStar(c.universe, star.raw as ObservedStar, { hypotheticalPlanets: !!opts.hypotheticalPlanets });
}

/** Catalogue scene of an observed star, if one of the 40 worlds models it. */
export function sceneIdOf(star: MapStar): string | undefined {
  if (star.provenance !== 'observed') return undefined;
  const id = (star.raw as ObservedStar).record.sceneId;
  return typeof id === 'string' && id ? id : undefined;
}
