// AiXenix Cosmos Lab web client: universe-map state that outlives the page (where the map was looking) and the one
// way into a local system from the map. Entering a system: build the scene first (no world change), then the replace
// guard (Save first / Discard / Cancel), then the normal guarded load. Cancel or a failure leaves the sandbox as it was.

import type { MapStar, Vec3 } from '../render/UniverseView';
import type { SceneFile } from '../content/catalog';
import { tx } from '../content/catalog';
import { Store } from './store';
import { navigate } from './router';
import { notify } from './notices';
import { settingsStore, t } from './settings';
import { confirmReplace } from './replaceGuard';
import { errorText, fetchScene, loadSceneDocument, type CosmosLocation } from './session';
import { validateSceneMeta } from './saves';
import { sceneIdOf, systemFor, type Cosmos } from './cosmos';

export interface MapView {
  targetPc: Vec3;
  distancePc: number;
}

export interface UniverseState {
  /** Last camera view, restored when the page opens again (navigation location). */
  view: MapView | null;
  /** Id of the selected star (address or obs.<id>) or galaxy ('galaxy:<id>'). */
  selectionId: string | null;
  entering: boolean;
}

const KEY = 'aixenix.cosmos.universe.v1';

function load(): UniverseState {
  try {
    const raw = localStorage.getItem(KEY);
    if (raw) {
      const v = JSON.parse(raw) as Partial<UniverseState>;
      const view = v.view;
      const okView =
        view && Array.isArray(view.targetPc) && view.targetPc.length === 3 && view.targetPc.every((x) => Number.isFinite(x)) && Number.isFinite(view.distancePc) && view.distancePc > 0;
      return { view: okView ? view : null, selectionId: typeof v.selectionId === 'string' ? v.selectionId : null, entering: false };
    }
  } catch {
    // ignore: a fresh view
  }
  return { view: null, selectionId: null, entering: false };
}

export const universeStore = new Store<UniverseState>(load());

let saveTimer = 0;
universeStore.subscribe(() => {
  window.clearTimeout(saveTimer);
  saveTimer = window.setTimeout(() => {
    const s = universeStore.get();
    try {
      localStorage.setItem(KEY, JSON.stringify({ view: s.view, selectionId: s.selectionId }));
    } catch {
      // storage unavailable: the view lasts for this tab
    }
  }, 400);
});

export function locationOf(c: Cosmos, star: MapStar): CosmosLocation {
  const sceneId = sceneIdOf(star);
  return { address: star.id, galaxyId: star.galaxyId, version: c.version, provenance: star.provenance, name: star.name, ...(sceneId ? { sceneId } : {}) };
}

/** Loads a star's system into the sandbox through the guarded path. Returns true when the sandbox now holds it. */
export async function enterStarSystem(c: Cosmos, star: MapStar, opts: { hypotheticalPlanets?: boolean } = {}): Promise<boolean> {
  if (universeStore.get().entering) return false;
  universeStore.set({ entering: true });
  try {
    const lang = settingsStore.get().lang;
    const location = locationOf(c, star);
    const name = tx(star.name, lang);
    let doc: SceneFile;
    let origin: Parameters<typeof loadSceneDocument>[1];
    const sceneId = location.sceneId;
    try {
      if (sceneId) {
        doc = await fetchScene(sceneId);
        origin = { kind: 'catalogue', sceneId };
      } else {
        doc = systemFor(c, star, opts);
        origin = { kind: 'cosmos', location };
      }
    } catch (e) {
      notify(t('uni.enterFailed', { reason: errorText(e) }), 'error');
      return false;
    }
    const bad = validateSceneMeta(doc);
    if (bad) {
      notify(t('uni.enterFailed', { reason: bad }), 'error');
      return false;
    }
    if (!(await confirmReplace())) return false;
    const ok = await loadSceneDocument(doc, origin, { location });
    if (ok) {
      notify(t('uni.entered', { name }), 'success');
      navigate('/sandbox');
    }
    return ok;
  } finally {
    universeStore.set({ entering: false });
  }
}

/** Opens a catalogue world from the map (e.g. a star the map cannot place), through the same guard. */
export async function enterCatalogueScene(sceneId: string, name: string, location: CosmosLocation | null): Promise<boolean> {
  if (universeStore.get().entering) return false;
  universeStore.set({ entering: true });
  try {
    let doc: SceneFile;
    try {
      doc = await fetchScene(sceneId);
    } catch (e) {
      notify(t('uni.enterFailed', { reason: errorText(e) }), 'error');
      return false;
    }
    if (!(await confirmReplace())) return false;
    const ok = await loadSceneDocument(doc, { kind: 'catalogue', sceneId }, { location });
    if (ok) {
      notify(t('uni.entered', { name }), 'success');
      navigate('/sandbox');
    }
    return ok;
  } finally {
    universeStore.set({ entering: false });
  }
}

/** Map route for a location (used by the sandbox's "back to the map"). */
export function mapRouteFor(loc: { galaxyId: string; address: string } | null): string {
  if (!loc) return '/universe';
  return `/universe/${encodeURIComponent(loc.galaxyId)}?star=${encodeURIComponent(loc.address)}`;
}
